import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A line of a claim's status log: a status the claim moved to, by whom, on the sheet's today then,
 * and the claim's due as computed at that moment (null when n/a).
 */
@Entity
@Table(name = "claim_log")
public class ClaimLogLine {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status;

    @Column(name = "by_user", nullable = false)
    private String by;

    @Column(name = "on_date", nullable = false)
    private LocalDate on;

    @Column(name = "due", precision = 14, scale = 2)
    private BigDecimal due;

    protected ClaimLogLine() {
    }

    public ClaimLogLine(ClaimStatus status, String by, LocalDate on, BigDecimal due) {
        this.status = status;
        this.by = by;
        this.on = on;
        this.due = due;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public String getBy() {
        return by;
    }

    public LocalDate getOn() {
        return on;
    }

    public BigDecimal getDue() {
        return due;
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status: DRAFT when added; a DRAFT claim may be opened, an OPEN one settled, and a DRAFT,
 * OPEN or PENDING one voided. An OPEN claim a clerk settles above the clerk limit goes PENDING, which
 * a steward approves (SETTLED) or rejects (back to OPEN). SETTLED and VOID are final. Only OPEN,
 * PENDING and SETTLED claims count.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Whether a claim may move from this status to {@code next}. */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case SETTLED, PENDING -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
            case DRAFT -> false;
        };
    }

    /** Whether a claim in this status counts toward what is claimed and due. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether a claim in this status is open: OPEN, or PENDING a steward's approval. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}
-- A claim's status log: one line per status it has had, oldest first (by id), with the user who
-- moved it there, the sheet's today then, and the claim's due as computed at that moment (null: n/a).
-- Claims added before the log have no lines.
CREATE TABLE claim_log (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    claim_id   BIGINT         NOT NULL REFERENCES claim (id),
    status     VARCHAR(16)    NOT NULL,
    by_user    VARCHAR(200)   NOT NULL,
    on_date    DATE           NOT NULL,
    due        DECIMAL(14, 2)
);
CREATE INDEX claim_log_claim ON claim_log (claim_id, id);
-- Closing a period also fixes each person's due-total for it at that moment, one row per person then
-- on the sheet; a person added later has no row and shows 0.00 for it. Reopening removes the rows.
-- The period's closed_total is the sum of these.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL,
    total     DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);

